function validate(input) {
  const [{ Store = [] }] = input;
  const bills = new Set();
  for (const [bill, customer, amount] of Store) {
    if (bill === null || customer === null || amount === null) return 'Store rows may not contain null.';
    if (bills.has(bill)) return `bill_id ${bill} appears twice in Store.`;
    if (amount < 0) return `Bill ${bill} has a negative amount.`;
    bills.add(bill);
  }
  return null;
}

