function generate(rand, size) {
  const small = size === 'small';
  const amounts = [100, 257, 394, 499, 500, 501, 549, 834];
  const rows = small ? Math.floor(rand() * 9) : 2000;
  const customers = small ? 4 : 600;
  const Store = [];
  for (let i = 0; i < rows; i++) {
    const amount = small ? amounts[Math.floor(rand() * amounts.length)] : Math.floor(rand() * 1001);
    // Bill ids are unique but not in insertion order.
    Store.push([small ? 3 * i + 1 + Math.floor(rand() * 3) : i + 1, 1 + Math.floor(rand() * customers), amount]);
  }
  return [{ Store }];
}
